            status: 'inProgress',
            timestamp: 'now',
            type: 'commandExecution',
        }
        const first = conversation(
            'codex.json',
            [{ ...message('message-1', 'Start'), agent: 'codex', sequence: 1 }, eventEntry(started)],
            'codex',
        )
        const { rerender } = renderChat(first)
        const completed = {
            ...started,
            id: 'command-completed',
            output: 'passed',
            status: 'completed',
        }

        rerender(
            <AppThemeProvider>
                <ActionConversationChat conversation={{
                    ...first, entries: first.entries.map((entry) => (
                        entry.kind === 'event' ? { ...completed, kind: 'event' } as const : entry
                    )),
                }} status="idle" />
            </AppThemeProvider>,
        )

        expect(screen.getAllByRole('button', { name: 'Command details: npm test' })).toHaveLength(1)
        expect(screen.getByText('Completed')).toBeInTheDocument()
    })

    it('keeps sticky position while reasoning and command output grow', () => {
        const firstActivity: AgentConversationEvent = {
            content: 'Inspect',
            id: 'reasoning-1',
            providerItemId: 'reasoning-1',
            sequence: 2,
            status: 'inProgress',
            summary: ['Inspect'],
            timestamp: 'now',
            type: 'reasoning',
        }
        const grownActivity = {
            ...firstActivity,
            content: 'Inspect more',
            summary: ['Inspect more'],
        }
        const commandActivity: AgentConversationEvent = {
            command: 'npm test',
            content: '',
            id: 'command-1',
            output: '',
            providerItemId: 'command-1',
            sequence: 3,
            status: 'inProgress',
            timestamp: 'now',
            type: 'commandExecution',
        }
        const first = conversation(
            'codex.json',
            [
                { ...message('message-1', 'Start'), agent: 'codex', sequence: 1 },
                eventEntry(firstActivity),
                eventEntry(commandActivity),
            ],
            'codex',
        )
        const grown = conversation(
            'codex.json',
            [
                ...first.entries.filter((entry) => entry.kind === 'message'),
                eventEntry(grownActivity),
                eventEntry({ ...commandActivity, content: 'line one\nline two', output: 'line one\nline two' }),
            ],
            'codex',
        )
        const { rerender } = renderChat(first)
        const viewport = screen.getByLabelText('Conversation chat')
        scrollHeight = 400

        rerender(
            <AppThemeProvider>
                <ActionConversationChat conversation={grown} status="idle" />
            </AppThemeProvider>,
        )

        expect(viewport.scrollTop).toBe(300)
    })
})

import type { AgentConversationEvent } from '../../data/data_types'

const COMMAND_PREVIEW_LENGTH = 96

export function eventStatusLabel(status?: string) {
    if (!status) return 'Unknown'
    if (status === 'inProgress' || status === 'running' || status === 'started') return 'Running'
    if (status === 'completed') return 'Completed'
    if (status === 'failed') return 'Failed'
    if (status === 'declined') return 'Declined'

    return status
}

export function eventHasError(status?: string) {
    return status === 'failed' || status === 'declined'
}

export function commandPreview(command?: string) {
    const oneLine = command?.replace(/\s+/gu, ' ').trim() ?? ''
    const characters = Array.from(oneLine)
    if (characters.length <= COMMAND_PREVIEW_LENGTH) return oneLine

    return `${characters.slice(0, COMMAND_PREVIEW_LENGTH - 1).join('')}â€¦`
}

export function readableEventText(value?: string) {
    return value?.trim() ? value.split(/\r?\n/u) : []
}

export function eventIdentity(event: AgentConversationEvent) {
    return event.providerItemId ?? event.id
}

