import { createRequire } from 'node:module';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { AGENT_FINISH_GRACE_MS, AgentRunnerService } = require('./agent_runner_service');

describe('AgentRunnerService state handling', () => {
    it('reports one diagnosed Codex cache error and suppresses repeats', async () => {
        const diagnoseCodexCacheError = vi.fn(async () => 'Codex versions differ. Update Codex.');
        const service = new AgentRunnerService({ diagnoseCodexCacheError });
        const run = {
            agent: 'codex',
            child: {},
            codexCacheErrorReported: false,
            conversation: { entries: [] },
            environment: { Path: 'C:\\tools' },
            executable: 'codex.cmd',
            id: 'run-1',
            nextSequence: 1,
            onEvent: vi.fn(),
            secretValues: new Set(),
            stderr: '',
            stderrBuffer: '',
            stderrHandling: Promise.resolve(),
        };
        service.processes.set('run-1', run);

        service.handleOutput('run-1', 'stderr', Buffer.from('failed to load models cache: broken\n'));
        service.handleOutput('run-1', 'stderr', Buffer.from('failed to renew cache TTL: broken\n'));
        await run.stderrHandling;

        expect(diagnoseCodexCacheError).toHaveBeenCalledOnce();
        expect(diagnoseCodexCacheError).toHaveBeenCalledWith(
            'failed to load models cache: broken',
            'codex.cmd',
            { Path: 'C:\\tools' },
        );
        expect(run.stderr).toBe('Codex versions differ. Update Codex.\n');
        expect(run.conversation.entries).toHaveLength(1);
        expect(run.onEvent).toHaveBeenCalledOnce();
    });

    it('consumes one queued revision exactly once', async () => {
        const sendMessage = vi.fn();
        const service = new AgentRunnerService({
            persistConversation: vi.fn(async () => undefined),
            persistConversationCheckpoint: vi.fn(async () => undefined),
        });
        service.processes.set('run-1', {
            conversation: { entries: [], status: 'running' },
            id: 'run-1',
            onEvent: vi.fn(),
            pendingApprovals: new Map(),
            persistence: Promise.resolve(),
            queuedMessage: null,
            queuedMessageRevision: -1,
            queuedMessageSessionId: 0,
            sentQueuedMessageRevision: -1,
            streaming: true,
            streamingAdapter: { sendMessage },
            turnActive: true,
            turnIndex: 1,
        });

        const sessionId = service.beginQueuedMessageDraft('run-1');
        service.setQueuedMessage('run-1', sessionId, 'approved', 0);
        await expect(service.sendQueuedMessage('run-1', sessionId, 0)).resolves.toEqual({ sent: true });
        await expect(service.sendQueuedMessage('run-1', sessionId, 0)).rejects.toThrow('already sent');

        expect(sendMessage).toHaveBeenCalledOnce();
        expect(sendMessage).toHaveBeenCalledWith('approved');
    });

    it('accepts revision zero from a new prompt session after renderer restart', () => {
        const service = new AgentRunnerService();
        };
        service.processes.set('run-1', run);
        const answers = { token: ['top-secret'] };

        const answering = service.answerQuestion('run-1', 7, answers);
        await vi.waitFor(() => expect(answerQuestion).toHaveBeenCalled());
        await service.handleStreamingEvent('run-1', { content: 'echo top-secret', type: 'assistant' });
        releaseAnswer();
        await answering;

        const answerMessage = run.conversation.entries.find((entry) => entry.kind === 'message' && entry.role === 'user');
        expect(answerMessage.content).toContain('token: [secret]');
        expect(run.stdout).toContain('echo [secret]');
        expect(JSON.stringify(run.onEvent.mock.calls)).not.toContain('top-secret');
    });

    it('creates separate assistant messages around intervening event', async () => {
        const service = new AgentRunnerService();
        const run = {
            providerEventEntryIndexes: new Map(),
            agent: 'codex',
            assistantItemIndex: 0,
            assistantItems: new Map(),
            conversation: { entries: [], status: 'running' },
            currentAssistantMessageId: null,
            id: 'run-1',
            nextSequence: 2,
            onEvent: vi.fn(),
            secretValues: new Set(),
            stdout: '',
            streaming: true,
            turnIndex: 1,
        };
        service.processes.set('run-1', run);

        await service.handleStreamingEvent('run-1', { itemId: 'message-1', type: 'assistantStarted' });
        await service.handleStreamingEvent('run-1', {
            event: {
                content: 'Thinking',
                label: 'Reasoning',
                providerItemId: 'reasoning-1',
                status: 'completed',
                type: 'reasoning',
            },
            type: 'event',
        });
        await service.handleStreamingEvent('run-1', { content: 'First', itemId: 'message-1', type: 'assistant' });
        await service.handleStreamingEvent('run-1', { itemId: 'message-2', type: 'assistantStarted' });
        await service.handleStreamingEvent('run-1', { content: 'Done', itemId: 'message-2', type: 'assistant' });

        expect(run.conversation.entries).toEqual([
            expect.objectContaining({ content: 'First', sequence: 2 }),
            expect.objectContaining({ providerItemId: 'reasoning-1', sequence: 3 }),
            expect.objectContaining({ content: 'Done', sequence: 4 }),
        ]);
    });

    it('updates an indexed event without scanning or appending conversation history', async () => {
        const service = new AgentRunnerService();
        const existingEvent = {
            content: 'Running',
            id: 'activity-1',
            kind: 'event',
            label: 'Command',
            providerItemId: 'command-1',
            sequence: 7,
            status: 'inProgress',
            timestamp: 'earlier',
            type: 'commandExecution',
        };
        const entries = [
            { content: 'started', id: 'started-1', kind: 'event', sequence: 1, timestamp: 'earlier', type: 'started' },
            existingEvent,
            { content: 'unrelated', id: 'event-1', kind: 'event', sequence: 8, timestamp: 'earlier', type: 'diagnostic' },
        ];
        entries.findIndex = vi.fn(() => { throw new Error('conversation history was scanned'); });
        const run = {
            providerEventEntryIndexes: new Map([['command-1', 1]]),
            conversation: { entries, status: 'running' },
            id: 'run-1',
            nextSequence: 9,
            onEvent: vi.fn(),
            secretValues: new Set(),
        };
        service.processes.set('run-1', run);

        await service.handleStreamingEvent('run-1', {
            event: {
                content: 'Completed',
                label: 'Command',
                providerItemId: 'command-1',
                status: 'completed',
                type: 'commandExecution',
            },
            type: 'event',
        });

        expect(entries.findIndex).not.toHaveBeenCalled();
        expect(run.conversation.entries).toHaveLength(3);
        expect(run.conversation.entries[1]).toMatchObject({
            content: 'Completed',
            id: 'activity-1',
            providerItemId: 'command-1',
            sequence: 7,
            status: 'completed',
        });
        expect(run.onEvent).toHaveBeenCalledWith(expect.objectContaining({
            event: expect.objectContaining({ content: 'Completed', id: 'activity-1' }),
            type: 'agentEvent',
        }));
    });

    it('does not append a user message when the provider write fails', async () => {
        const writeError = new Error('stdin write failed');
        const service = new AgentRunnerService({
            persistConversation: vi.fn(async () => undefined),
            persistConversationCheckpoint: vi.fn(async () => undefined),
            terminateProcessTree: vi.fn(async () => undefined),
        });
        const run = {
            child: { stdin: { end: vi.fn() } },
            conversation: {
                entries: [{ content: 'initial', id: 'user-1', kind: 'message', role: 'user', timestamp: 'now' }],
                status: 'waitingForInput',
            },
const crypto = require('node:crypto');
const path = require('node:path');
const crossSpawn = require('cross-spawn');

const {
    accumulateUsage,
    createProviderEventEntry,
    createConversation,
    createEventEntry,
    createMessageEntry,
    updateProviderSession,
} = require('./agent_conversation');
const {
    conversationReference,
    persistConversation,
    persistConversationCheckpoint,
} = require('./agent_conversation_persistence');
const { JsonLineBuffer } = require('./agent_event_utils');
const { createAgentProviderProtocolParser } = require('./agent_provider_protocol');
const { createAgentStreamingAdapter } = require('./agent_streaming_adapter');
const { AgentExecutableResolver } = require('./agent_executable_availability');
const { createAgentEnvironment } = require('./agent_environment');
const { diagnoseCodexCacheError, isCodexCacheError } = require('./agent_codex_cache_diagnostic');
const { terminateProcessTree } = require('../process_tree');
const { assertGitRoot, ensureInsideRoot, requireRootPath } = require('../../git/git_commands');

const HIDDEN_STDERR_LINES = [
    /^completed$/i,
    /^Debugger listening on ws:\/\//,
    /^For help, see: https:\/\/nodejs\.org\/en\/docs\/inspector\/?$/,
    /^Debugger attached\.$/,
    /^Reading additional input from stdin\.\.\.$/,
    /^Waiting for the debugger to disconnect\.\.\.$/,
];
const AGENT_FINISH_GRACE_MS = 5_000;

function isHiddenStderrLine(line) {
    return HIDDEN_STDERR_LINES.some((pattern) => pattern.test(line.trim()));
}

function filterCompleteStderrLines(content) {
    const parts = content.split(/(\r\n|\r|\n)/);
    const remainder = parts.pop();
    const visibleParts = [];
    for (let index = 0; index < parts.length; index += 2) {
        const line = parts[index];
        const delimiter = parts[index + 1];
        if (!isHiddenStderrLine(line)) visibleParts.push(`${line}${delimiter}`);
    }

    return { content: visibleParts.join(''), remainder };
}

function requireString(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing agent ${fieldName}`);

    return value;
}

function requireProjectFolder(value) {
    if (typeof value !== 'string') throw new Error('Missing agent projectFolder');

    return value;
}

function requireCommand(value) {
    if (!Array.isArray(value) || value.length === 0) throw new Error('Missing agent command');
    value.forEach((argument, index) => requireString(argument, `command[${index}]`));

    return value;
}

function readOptionalString(value, fieldName) {
    if (value === undefined || value === null) return null;
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing agent ${fieldName}`);

    return value;
}

function emitRunEvent(run, event) {
    if (!run.onEvent) return;

    run.onEvent({ ...event, runId: run.id });
}

function writeJsonLine(stream, message) {
    return new Promise((resolve, reject) => {
        stream.write(`${JSON.stringify(message)}\n`, (error) => {
            if (error) {
                reject(error);
                return;
            }

            resolve();
        });
    });
}

function queueInteractionWrite(run, operation) {
    run.interactionWrites ??= Promise.resolve();
    const write = run.interactionWrites.then(operation);
    run.interactionWrites = write.catch(() => undefined);

    return write;
}

function hasPendingInteraction(run) {
    return run.waitingForQuestion || run.pendingApprovals.size > 0;
}

function secretAnswerValues(questions, answers) {
    const secretQuestionIds = new Set(questions.filter(({ isSecret }) => isSecret).map(({ id }) => id));

    return Object.entries(answers)
        .filter(([questionId]) => secretQuestionIds.has(questionId))
        .flatMap(([, answer]) => Array.isArray(answer) ? answer : [answer])
        .filter((answer) => typeof answer === 'string' && answer.length > 0);
}

function redactSecrets(content, secretValues) {
    if (typeof content !== 'string' || !secretValues || secretValues.size === 0) return content;

    return [...secretValues]
        .sort((first, second) => second.length - first.length)
        .reduce((redacted, secret) => redacted.split(secret).join('[secret]'), content);
}

function redactTextArray(values, secretValues) {
    return values.map((value) => redactSecrets(value, secretValues));
}

function redactConversationEvent(event, secretValues) {
    return {
        ...event,
        command: redactSecrets(event.command, secretValues),
        content: redactSecrets(event.content, secretValues),
        details: Array.isArray(event.details) ? redactTextArray(event.details, secretValues) : event.details,
        label: redactSecrets(event.label, secretValues),
        output: redactSecrets(event.output, secretValues),
        summary: Array.isArray(event.summary) ? redactTextArray(event.summary, secretValues) : event.summary,
        workingDirectory: redactSecrets(event.workingDirectory, secretValues),
    };
