export type CardAgentState = 'idle' | 'running' | 'unseen result' | 'waiting for input'

function isConversationWaiting(card: ProjectCard) {
    return card.agentConversations.some((conversation) => {
        if (conversation.status === 'waitingForInput') return true
        if (conversation.status !== 'running') return false

        const stateEvent = conversation.entries.findLast((entry) => (
            entry.kind === 'event' && (entry.type === 'waiting' || entry.type === 'resumed')
        ))

        return stateEvent?.kind === 'event' && stateEvent.type === 'waiting'
    })
}

/** True when the card has at least one agent conversation still running. */
export function hasRunningConversation(card: ProjectCard) {
    return card.agentConversations.some((conversation) => (
        conversation.status === 'running' || conversation.status === 'waitingForInput'
    ))
}

/** Resolve the single agent state shown for a card, mirroring the priority waiting > running > unseen > idle. */
export function cardAgentState(projectKey: string, card: ProjectCard): CardAgentState {
    if (isConversationWaiting(card)) return 'waiting for input'
    if (hasRunningConversation(card)) return 'running'
    if (hasUnseenAgentResult(projectKey, card.path, card.agentConversations)) return 'unseen result'

    return 'idle'
}

/** Human-readable description of an agent state, or null when idle. */
export function agentStateDescription(agentState: CardAgentState): string | null {
    if (agentState === 'waiting for input') return 'Agent is waiting for input'
    if (agentState === 'running') return 'Agent is running'
    if (agentState === 'unseen result') return 'New agent result available'

    return null
}

import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import type { DataService } from '../data/data_service'
import { dataService } from '../data/data_service'
import { register } from '../service_injector'

const CARD_ACTION_POPUPS_CHANGED_EVENT = 'changed'

export interface CardActionPopupEntry {
    anchorElement: HTMLElement
    context: ActionContext
    fallbackAnchorElement: HTMLElement
    id: string
    projectKey: string
}

function projectKey(service: DataService) {
    const project = service.getState().project

    return project ? `${project.id}:${project.branch}` : null
}

function createFallbackAnchor(anchorElement: HTMLElement) {
    const bounds = anchorElement.getBoundingClientRect()
    const fallbackAnchorElement = document.createElement('span')
    fallbackAnchorElement.setAttribute('aria-hidden', 'true')
    fallbackAnchorElement.dataset.cardActionPopupAnchor = 'true'
    Object.assign(fallbackAnchorElement.style, {
        height: `${bounds.height}px`,
        left: `${bounds.left}px`,
        pointerEvents: 'none',
        position: 'fixed',
        top: `${bounds.top}px`,
        visibility: 'hidden',
        width: `${bounds.width}px`,
    })
    document.body.append(fallbackAnchorElement)

    return fallbackAnchorElement
}

/** Owns every open card action popup independently from card component lifetimes. */
export class CardActionPopupService extends EventTarget {
    private readonly dataService: DataService
    private entries: CardActionPopupEntry[] = []
    private nextId = 1
    private currentProjectKey: string | null

    constructor(dataServiceInstance: DataService) {
        super()
        this.dataService = dataServiceInstance
        this.currentProjectKey = projectKey(this.dataService)
        this.dataService.addEventListener('changed', this.handleDataServiceChanged)
    }

    getSnapshot() {
        return this.entries
    }

    toggle(context: ActionContext, anchorElement: HTMLElement, activeProjectKey: string) {
        const contextIdentity = actionContextIdentity(context)
        const existing = this.entries.find((entry) => actionContextIdentity(entry.context) === contextIdentity)
        if (existing) {
            this.close(existing.id)
            return
        }

        if (!context.cardInternalId) throw new Error('Cannot open a card action popup without a card internal ID')

        const entry = {
            anchorElement,
            context: { ...context },
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-action-popup-${this.nextId}`,
            projectKey: activeProjectKey,
        }
        this.nextId += 1
        this.setEntries([...this.entries, entry])
    }

    close(id: string) {
        const entry = this.entries.find((candidate) => candidate.id === id)
        if (!entry) return

        entry.fallbackAnchorElement.remove()
        this.setEntries(this.entries.filter((candidate) => candidate.id !== id))
    }

    activate(id: string) {
        const entryIndex = this.entries.findIndex((entry) => entry.id === id)
        if (entryIndex < 0 || entryIndex === this.entries.length - 1) return

        const entry = this.entries[entryIndex]
        this.setEntries([...this.entries.filter((candidate) => candidate.id !== id), entry])
    }

    clear() {
        if (this.entries.length === 0) return

        this.entries.forEach(({ fallbackAnchorElement }) => fallbackAnchorElement.remove())
        this.setEntries([])
    }

    private readonly handleDataServiceChanged = () => {
        const nextProjectKey = projectKey(this.dataService)
        if (nextProjectKey === this.currentProjectKey) return

        this.currentProjectKey = nextProjectKey
        this.clear()
    }

    private setEntries(entries: CardActionPopupEntry[]) {
        this.entries = entries
        this.dispatchEvent(new Event(CARD_ACTION_POPUPS_CHANGED_EVENT))
    }
}

export const cardActionPopupService = register('cardActionPopupService', new CardActionPopupService(dataService))

export function subscribeCardActionPopups(onStoreChange: () => void) {
    cardActionPopupService.addEventListener(CARD_ACTION_POPUPS_CHANGED_EVENT, onStoreChange)

    return () => cardActionPopupService.removeEventListener(CARD_ACTION_POPUPS_CHANGED_EVENT, onStoreChange)
}

import { useCallback, useSyncExternalStore } from 'react'
import {
    agentAcknowledgementCheckpoint,
    agentAcknowledgementService,
} from '../../services/agents/agent_acknowledgement_service'

/** Subscribes a leaf owner to the acknowledgement checkpoint for one card. */
export function useAgentAcknowledgement(projectId: string | null, cardPath: string | null | undefined) {
    const subscribe = useCallback((onStoreChange: () => void) => (
        projectId && cardPath ? agentAcknowledgementService.subscribeCard(projectId, cardPath, onStoreChange) : () => undefined
    ), [cardPath, projectId])
    const getSnapshot = useCallback(() => (
        projectId && cardPath ? agentAcknowledgementCheckpoint(projectId, cardPath) : null
    ), [cardPath, projectId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

import type { ActionContext } from '../../data/action_context'
import type { AgentConversation } from '../../data/data_types'
import { latestUnseenAgentResult } from '../../services/agents/agent_acknowledgement_service'
import { useActionContextCard } from './use_action_context_card'
import { useAgentAcknowledgement } from './use_agent_acknowledgements'

/** Owns acknowledgement and conversation data for one card-scoped action leaf. */
export function useCardActionUnseenResults(
    actionIds: string[],
    context: ActionContext,
    projectKey: string | null,
): AgentConversation[] {
    const { card, cardPath } = useActionContextCard(context)
    const conversations = card?.agentConversations ?? []
    useAgentAcknowledgement(projectKey, cardPath)

    if (!projectKey || !cardPath) return []

    return actionIds.flatMap((actionId) => {
        const conversation = latestUnseenAgentResult(projectKey, cardPath, conversations, actionId)

        return conversation ? [conversation] : []
    })
}

import { useCallback, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../data/action_context'
import type { AgentConversation } from '../../data/data_types'
import { useActionRunSelector } from '../hooks/use_action_runs'
import { agentAcknowledgementService } from '../../services/agents/agent_acknowledgement_service'
import { dialogService } from '../../services/dialog_service'
import { useActionContextCard } from '../hooks/use_action_context_card'
import { ActionConversationChat } from './action_conversation_chat'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationChatOwnerProps {
    actionId: string
    context: ActionContext
    projectKey: string | null
    store: ActionConversationStore
}

function acknowledgeConversation(projectKey: string, cardPath: string, conversation: AgentConversation) {
    try {
        agentAcknowledgementService.acknowledge(projectKey, cardPath, [conversation])
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Card conversation could not be acknowledged' })
    }
}

/** Subscribes only chat boundary to selected and canonical live conversation changes. */
export function ActionConversationChatOwner(props: ActionConversationChatOwnerProps) {
    const { actionId, context, projectKey, store } = props
    const liveConversation = useActionRunSelector(actionId, context, (run) => run?.conversation ?? null)
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? 'idle')
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const { cardPath } = useActionContextCard(context)
    const conversation = liveConversation ?? selectedConversation
    const status = runStatus === 'idle' && conversation?.status === 'waitingForInput' ? 'waitingForInput' : runStatus
    const handleConversationViewed = useCallback((viewedConversation: AgentConversation) => {
        if (projectKey && cardPath) acknowledgeConversation(projectKey, cardPath, viewedConversation)
    }, [cardPath, projectKey])
    const onConversationViewed = projectKey && cardPath ? handleConversationViewed : undefined

    return <ActionConversationChat conversation={conversation} onConversationViewed={onConversationViewed} status={status} />
}

import { Box, Button, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import Play from 'mdi-material-ui/Play'
import type { MouseEvent } from 'react'
import type { ActionContext } from '../../data/action_context'
import type { ProjectCard } from '../../data/data_types'
import { cardActionPopupService } from '../../services/actions/card_action_popup_service'
